import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'
import { rateLimit } from '@/lib/rate-limit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export async function POST(req: NextRequest) {
  // Anti-spam: 5 reviews per phone per day, 20 per IP per day.
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (!rateLimit(`review:ip:${ip}`, 20, 24 * 60 * 60 * 1000)) {
    return NextResponse.json({ error: 'Too many reviews from this network.' }, { status: 429 })
  }

  try {
    const body = await req.json()
    const farmer_id: unknown = body.farmer_id
    const reviewer_name: unknown = body.reviewer_name
    const reviewer_phone: unknown = body.reviewer_phone
    const star_rating: unknown = body.star_rating
    const review_text: unknown = body.review_text
    const produce_ordered: unknown = body.produce_ordered

    if (typeof farmer_id !== 'string' || !UUID_RE.test(farmer_id)) {
      return NextResponse.json({ error: 'Invalid farmer id.' }, { status: 400 })
    }
    if (typeof reviewer_name !== 'string' || !reviewer_name.trim()) {
      return NextResponse.json({ error: 'Reviewer name is required.' }, { status: 400 })
    }
    if (typeof star_rating !== 'number' || star_rating < 1 || star_rating > 5) {
      return NextResponse.json({ error: 'Rating must be 1-5.' }, { status: 400 })
    }

    // Phone is required so each reviewer is uniquely identifiable for the
    // duplicate-check below. Without it any troll can flood reviews.
    const phoneDigits = reviewer_phone ? String(reviewer_phone).replace(/\D/g, '').slice(-10) : ''
    if (phoneDigits.length !== 10) {
      return NextResponse.json({ error: 'Enter your phone to submit a review.' }, { status: 400 })
    }

    // Per-phone burst guard — same phone can submit at most 5 reviews / day total.
    if (!rateLimit(`review:phone:${phoneDigits}`, 5, 24 * 60 * 60 * 1000)) {
      return NextResponse.json({ error: 'You\'ve submitted too many reviews recently.' }, { status: 429 })
    }

    const trimmedName = reviewer_name.trim().slice(0, 80)
    const trimmedText = typeof review_text === 'string' ? review_text.trim().slice(0, 1000) : ''
    const trimmedProduce = typeof produce_ordered === 'string' ? produce_ordered.trim().slice(0, 100) : ''

    // Require service role — never fall back to anon (would mask RLS misconfig
    // and let the route silently break in production).
    const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY
    if (!serviceKey) {
      console.error('[YFF reviews] SUPABASE_SERVICE_ROLE_KEY missing')
      return NextResponse.json({ error: 'Reviews service is misconfigured.' }, { status: 500 })
    }
    const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, serviceKey)

    const { data: existing } = await supabase
      .from('reviews')
      .select('id')
      .eq('farmer_id', farmer_id)
      .eq('reviewer_phone', phoneDigits)
      .maybeSingle()
    if (existing) {
      return NextResponse.json({ error: 'already_reviewed' }, { status: 409 })
    }

    const insertPayload: Record<string, unknown> = {
      farmer_id,
      reviewer_name: trimmedName,
      reviewer_phone: phoneDigits,
      star_rating,
      review_text: trimmedText || null,
      produce_ordered: trimmedProduce || null,
      approved: true,
    }

    const { data: review, error } = await supabase
      .from('reviews')
      .insert(insertPayload)
      .select('*')
      .single()

    if (error) return NextResponse.json({ error: error.message }, { status: 500 })

    const { data: allReviews } = await supabase
      .from('reviews')
      .select('star_rating')
      .eq('farmer_id', farmer_id)
      .eq('approved', true)

    if (allReviews && allReviews.length > 0) {
      const avg =
        allReviews.reduce((sum: number, r: { star_rating: number }) => sum + r.star_rating, 0) /
        allReviews.length
      await supabase
        .from('farmers')
        .update({
          rating_avg: Math.round(avg * 10) / 10,
          buyer_count: allReviews.length,
        })
        .eq('id', farmer_id)
    }

    return NextResponse.json({ review })
  } catch {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState, useEffect } from 'react'
import { useLang } from '@/lib/LanguageContext'

type Review = {
  id: string
  reviewer_name: string
  reviewer_location?: string
  star_rating: number
  review_text?: string
  produce_ordered?: string
  created_at: string
}

export default function ReviewsTab({
  reviews: initialReviews,
  farmerId,
}: {
  reviews: Record<string, unknown>[]
  farmerId: string
}) {
  const { tx, L } = useLang()
  const [reviews, setReviews] = useState<Review[]>(initialReviews as Review[])
  const [showForm, setShowForm] = useState(false)
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [rating, setRating] = useState(0)
  const [hoverRating, setHoverRating] = useState(0)
  const [reviewText, setReviewText] = useState('')
  const [produceBought, setProduceBought] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [done, setDone] = useState(false)

  // Restore already-reviewed state from localStorage on mount
  useEffect(() => {
    if (localStorage.getItem(`yff_reviewed_${farmerId}`)) setDone(true)
  }, [farmerId])

  const avg =
    reviews.length > 0
      ? reviews.reduce((sum, r) => sum + r.star_rating, 0) / reviews.length
      : 0

  const counts = [5, 4, 3, 2, 1].map((star) => ({
    star,
    count: reviews.filter((r) => r.star_rating === star).length,
  }))

  const resetForm = () => {
    setName('')
    setPhone('')
    setRating(0)
    setHoverRating(0)
    setReviewText('')
    setProduceBought('')
    setError('')
  }

  const handleSubmit = async () => {
    if (!name.trim() || phone.replace(/\D/g, '').length < 10 || rating === 0) {
      setError(tx.reviewRequiredFields)
      return
    }
    setSubmitting(true)
    setError('')

    const res = await fetch('/api/reviews', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        farmer_id: farmerId,
        reviewer_name: name.trim(),
        reviewer_phone: phone.replace(/\D/g, '').slice(-10),
        star_rating: rating,
        review_text: reviewText.trim() || null,
        produce_ordered: produceBought.trim() || null,
      }),
    })

    const json = await res.json().catch(() => ({}))
    setSubmitting(false)

    if (res.status === 409 || json.error === 'already_reviewed') {
      localStorage.setItem(`yff_reviewed_${farmerId}`, '1')
      setDone(true)
      setShowForm(false)
      resetForm()
      return
    }

    if (!res.ok) {
      setError(json.error ?? tx.reviewError)
      return
    }

    if (json.review) setReviews((prev) => [json.review as Review, ...prev])
    localStorage.setItem(`yff_reviewed_${farmerId}`, '1')
    setDone(true)
    setShowForm(false)
    resetForm()
  }

  return (
    <div className="space-y-4">
      {/* CTA / success */}
      {done ? (
        <div className="bg-green-50 border border-green-200 rounded-xl p-4 text-center">
          <div className="text-3xl mb-1">⭐</div>
          <p className="font-bold text-green-800 text-sm">{tx.reviewSubmitted}</p>
        </div>
      ) : !showForm ? (
        <button
          onClick={() => setShowForm(true)}
          className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
        >
          ✏️ {tx.writeReview}
        </button>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100 bg-gray-50">
            <h3 className="font-extrabold text-gray-900 text-sm">{tx.writeReview}</h3>
            <button
              onClick={() => { setShowForm(false); resetForm() }}
              className="text-gray-400 text-2xl leading-none p-1"
            >
              ×
            </button>
          </div>

          <div className="p-4 space-y-4">
            {/* Star picker */}
            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-2">
                {tx.starRatingLabel}
              </label>
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <button
                    key={s}
                    onClick={() => setRating(s)}
                    onMouseEnter={() => setHoverRating(s)}
                    onMouseLeave={() => setHoverRating(0)}
                    className="text-4xl leading-none transition-transform active:scale-110"
                    aria-label={`${s} stars`}
                  >
                    <span className={(hoverRating || rating) >= s ? 'text-yellow-400' : 'text-gray-200'}>
                      ★
                    </span>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewerNameLabel}
              </label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ramya"
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
              />
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewerPhoneLabel}
              </label>
              <div className="flex gap-2">
                <span className="flex items-center px-3 bg-gray-50 border border-gray-200 rounded-xl text-sm text-gray-600 font-medium">
                  +91
                </span>
                <input
                  type="tel"
                  inputMode="numeric"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  placeholder="9876543210"
                  maxLength={10}
                  className="flex-1 border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
                />
              </div>
              <p className="text-[11px] text-gray-400 mt-1">{L('Used only to verify your review.', 'సమీక్షను ధృవీకరించడానికి మాత్రమే.')}</p>
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.produceOrderedLabel}
              </label>
              <input
                type="text"
                value={produceBought}
                onChange={(e) => setProduceBought(e.target.value)}
                placeholder="e.g. Tomato, Brinjal"
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm focus:border-green-500 focus:outline-none"
              />
            </div>

            <div>
              <label className="text-xs font-bold text-gray-600 uppercase tracking-wide block mb-1.5">
                {tx.reviewTextLabel}
              </label>
              <textarea
                value={reviewText}
                onChange={(e) => setReviewText(e.target.value.slice(0, 400))}
                placeholder="Share your experience with this farmer..."
                rows={3}
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm resize-none focus:border-green-500 focus:outline-none"
              />
              <p className="text-right text-xs text-gray-400">{reviewText.length}/400</p>
            </div>

            {error && (
              <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2">{error}</p>
            )}

            <div className="flex gap-3">
              <button
                onClick={() => { setShowForm(false); resetForm() }}
                className="flex-1 border-2 border-gray-200 text-gray-600 font-semibold py-3 rounded-xl text-sm"
              >
                {tx.cancelBtn}
              </button>
              <button
                onClick={handleSubmit}
                disabled={submitting}
                className="flex-1 bg-green-700 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-50 active:bg-green-800"
              >
                {submitting ? tx.submittingReview : tx.submitReview}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Rating summary */}
      {reviews.length > 0 && (
        <div className="bg-white rounded-xl border border-gray-100 p-4">
          <div className="flex items-center gap-4">
            <div className="text-center">
              <p className="text-4xl font-bold text-gray-900">{avg.toFixed(1)}</p>
              <div className="flex justify-center mt-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <span key={s} className={`text-base ${s <= Math.round(avg) ? 'text-yellow-400' : 'text-gray-200'}`}>
                    ★
                  </span>
                ))}
              </div>
              <p className="text-xs text-gray-500 mt-1">{reviews.length} {tx.reviews}</p>
            </div>
            <div className="flex-1 space-y-1">
              {counts.map(({ star, count }) => (
                <div key={star} className="flex items-center gap-2">
                  <span className="text-xs text-gray-500 w-3">{star}</span>
                  <div className="flex-1 bg-gray-100 rounded-full h-2">
                    <div
                      className="bg-yellow-400 h-2 rounded-full"
                      style={{ width: reviews.length ? `${(count / reviews.length) * 100}%` : '0%' }}
                    />
                  </div>
                  <span className="text-xs text-gray-500 w-4">{count}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {reviews.length === 0 && !showForm && !done && (
        <div className="text-center py-8 text-gray-400 text-sm">{tx.noReviews}</div>
      )}

      {/* Individual reviews */}
      {reviews.length > 0 && (
        <div className="space-y-3">
          {reviews.map((review) => (
            <div key={review.id} className="bg-white rounded-xl border border-gray-100 p-4">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-full bg-green-100 flex items-center justify-center text-green-800 font-bold text-sm flex-shrink-0">
                    {review.reviewer_name.slice(0, 2).toUpperCase()}
                  </div>
                  <div>
                    <p className="text-sm font-semibold text-gray-900">{review.reviewer_name}</p>
                    {review.reviewer_location && (
                      <p className="text-xs text-gray-500">{review.reviewer_location}</p>
                    )}
                  </div>
                </div>
                <div className="text-right flex-shrink-0">
                  <div className="flex justify-end">
                    {[1, 2, 3, 4, 5].map((s) => (
                      <span key={s} className={`text-sm ${s <= review.star_rating ? 'text-yellow-400' : 'text-gray-200'}`}>
                        ★
                      </span>
                    ))}
                  </div>
                  <p className="text-[10px] text-gray-400 mt-0.5">
                    {new Date(review.created_at).toLocaleDateString('en-IN', {
                      day: 'numeric',
                      month: 'short',
                      year: 'numeric',
                    })}
                  </p>
                </div>
              </div>
              {review.review_text && (
                <p className="text-sm text-gray-600 mt-3 leading-relaxed">{review.review_text}</p>
              )}
              {review.produce_ordered && (
                <p className="text-xs text-green-700 font-semibold mt-2">
                  {tx.bought} {review.produce_ordered}
                </p>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

